class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        pre_max = nums[0]
        times = 0
        for i in range(1, n):
            if nums[i] <= pre_max:
                steps = pre_max - nums[i] + 1
                times += steps
                pre_max = nums[i] + steps
            else:
                pre_max = nums[i]
        return times

class Solution {
    public int minOperations(int[] nums) {
        int n = nums.length;
        int preMax = nums[0];
        int times = 0;
        for (int i = 1; i < n; ++i) {
            if (nums[i] <= preMax) {
                int steps = preMax - nums[i] + 1;
                times += steps;
                preMax = nums[i] + steps;
            } else {
                preMax = nums[i];
            }
        }
        return times;
    }
}

class Solution(object):
    def minOperations(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        ans = 0
        cur_num = nums[0]
        for i in range(1, len(nums)):
            if nums[i] <= cur_num:
                ans += (cur_num - nums[i] + 1)
                cur_num = cur_num + 1
            else:
                cur_num = nums[i]
        return ans
